(function () {

    const G = "https://gemini.google.com";
    const YT = "https://www.youtube.com";

    const cooldownTime = 10 * 60 * 1000;

    let status = String(Bot.getStatus() || "idle");
    const url = window.location.href;

    // =========================
    // SAFE STATUS PARSE
    // =========================
    function isCooldown(s) {
        return typeof s === "string" && s.startsWith("cooldown:");
    }

    function getCooldownTime(s) {
        try {
            return parseInt(s.split(":")[1]);
        } catch (e) {
            return 0;
        }
    }

    // =========================
    // COOLDOWN HANDLER
    // =========================
    if (isCooldown(status)) {

        const saved = getCooldownTime(status);
        const now = Date.now();

        if (now - saved < cooldownTime) {

            const left = Math.ceil((cooldownTime - (now - saved)) / 1000);

            console.log("⏳ Cooldown চলছে:", left, "sec");

            return;
        }

        console.log("🚀 Cooldown শেষ");
        Bot.setStatus("idle");
        status = "idle";
    }

    // =========================
    // EMERGENCY RECOVERY
    // =========================
    if (!status || status === "undefined" || status === "null") {
        Bot.setStatus("idle");
        status = "idle";
    }

    // =========================
    // FORCE NAVIGATION
    // =========================
    if (!url.includes("gemini.google.com")) {

        console.log("🌐 Gemini এ যাচ্ছি...");

        Bot.setStatus("working");

        Bot.search(G);

        return;
    }

    // =========================
    // GENTLE WAIT (UI LOAD)
    // =========================
    setTimeout(() => {

        const editor =
            document.querySelector('div[contenteditable="true"]') ||
            document.querySelector("textarea");

        if (!editor) {

            console.log("❌ Editor পাওয়া যায়নি");

            return;
        }

        editor.focus();

        // safer input method
        if ("value" in editor) {
            editor.value = "Hi";
        } else {
            editor.innerText = "Hi";
        }

        editor.dispatchEvent(new Event("input", { bubbles: true }));

        console.log("✍️ Message typed");

        setTimeout(() => {

            const sendBtn =
                document.querySelector('button[aria-label*="Send"]') ||
                [...document.querySelectorAll("button")]
                    .find(b => (b.innerText || "").toLowerCase().includes("send"));

            if (sendBtn) {
                sendBtn.click();
            } else {
                editor.dispatchEvent(
                    new KeyboardEvent("keydown", {
                        bubbles: true,
                        key: "Enter"
                    })
                );
            }

            console.log("📤 Sent");

            setTimeout(() => {

                Bot.setStatus("cooldown:" + Date.now());

                console.log("➡️ YouTube এ যাচ্ছি");

                Bot.search(YT);

            }, 3000);

        }, 1200);

    }, 6000);

})();
